local function decodepayload(encoded,want)local raw=b85(encoded,want)if byte(raw,1)~=77 or byte(raw,2)~=86 or byte(raw,3)~=73 or byte(raw,4)~=50 or sub(raw,5,20)~=expected then die()end local plainlen=u32at(raw,21)local packedlen=u32at(raw,25)local wantcrc=u32at(raw,29)local nonce=u32at(raw,33)local tag=sub(raw,37,68)local encrypted=sub(raw,69)if #encrypted~=packedlen or hmac(key,sub(raw,1,36)..encrypted)~=tag then die()end local image=lzss(crypt(encrypted,nonce))if #image~=plainlen or crc(image)~=wantcrc then die()end return image end
